package com.taxplatform.startup;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class NativeImportTests {
    private static int passed;
    private NativeImportTests(){ }
    @FunctionalInterface private interface Test{void run()throws Exception;}
    private static void check(String name,Test work)throws Exception{work.run();passed++;System.out.println("PASS "+name);}
    private static void eq(Object a,Object b){if(!java.util.Objects.equals(a,b))throw new AssertionError("native proposal assertion failed");}
    private static void fail(int status,String code,Runnable work){try{work.run();}catch(Workspace.Problem e){eq(e.status,status);eq(e.code,code);return;}throw new AssertionError("expected rejection: "+code);}
    private static final class Time extends Clock{Instant now=Instant.parse("2026-11-01T00:00:00Z");@Override public ZoneId getZone(){return ZoneOffset.UTC;}@Override public Clock withZone(ZoneId z){return this;}@Override public Instant instant(){return now;}}
    private static Map<String,NativeImports.Proposal> offered(){return Map.of("SALARY",new NativeImports.Proposal("SALARY","800000.00","/ITR/ITR1/ITR1_IncomeDeductions/GrossSalary"),"SAVINGS_INTEREST",new NativeImports.Proposal("SAVINGS_INTEREST","5000.00","/ITR/ITR1/ITR1_IncomeDeductions/OthersInc/OthersIncDtlsOthSrc/0/OthSrcOthAmount"));}
    private static Map<String,Object> selection(String field,String amount){return SelfServiceTests.body("field",field,"amount",amount,"whole_category_confirmed",true,"replace_input_confirmed",true);}
    private static Map<String,Object> command(Workspace w,String owner,String id){return SelfServiceTests.body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preview_id","A".repeat(43),"same_taxpayer_confirmed",true,"selections",List.of(selection("SALARY","800000.00"),selection("SAVINGS_INTEREST","5000.00")));}
    private static NativeImports.Preview preview(Workspace w,String owner,String id){return new NativeImports.Preview(owner,id,((Number)w.readCase(owner,id).get("revision")).longValue(),Instant.now().plusSeconds(600),offered());}
    private static String create(Workspace w,String owner){return (String)w.createCase(owner,SelfServiceTests.body("title","Native sample","request_id",Workspace.id())).get("id");}
    private static void edit(Workspace w,String owner,String id,String operation,Object... extra){Map<String,Object> b=SelfServiceTests.body("operation",operation,"request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"));b.putAll(SelfServiceTests.body(extra));w.edit(owner,id,b);}
    private static Map<String,Object> worker(){return SelfServiceTests.body("contract_version","native-itr-preflight.v1","schema_id",NativeImports.SCHEMA_ID,"schema_sha256",NativeImports.SCHEMA_SHA,"schema_validation","PASS","document_format","MATCH","proposal_pack","AVAILABLE","issues",List.of(),"warnings",List.of(),"proposals",List.of(Map.of("field","SALARY","amount","800000.00","source_path","/ITR/ITR1/ITR1_IncomeDeductions/GrossSalary")),"filing_available",true,"PAN","ZZZZZ0000Z","TotalTaxPayable",987654321L);}
    public static void main(String[] args)throws Exception{
        check("worker projection never passes source tax identity or authority fields",()->{var out=NativeImports.projection(worker());eq(out.get("filing_available"),false);eq(out.get("business_rules_validated"),false);eq(Json.encode(out).contains("ZZZZZ0000Z"),false);eq(Json.encode(out).contains("987654321"),false);});
        check("worker paths and codes cannot echo unknown private values",()->{var raw=worker();raw.put("schema_validation","FAIL");raw.put("proposals",List.of());raw.put("issues",List.of(Map.of("path","/ITR/ITR1/PersonalInfo/ZZZZZ0000Z","code","ZZZZZ0000Z")));eq(Json.encode(NativeImports.projection(raw)).contains("ZZZZZ0000Z"),false);});
        check("worker cannot offer tax fields precision drift or proposals on failed schema",()->{var raw=worker();raw.put("proposals",List.of(Map.of("field","TOTAL_TAX","amount","800000.00","source_path","/ITR/ITR1/ITR1_IncomeDeductions/GrossSalary")));fail(503,"NATIVE_WORKER_CONTRACT_REJECTED",()->NativeImports.projection(raw));raw.put("proposals",worker().get("proposals"));raw.put("schema_validation","FAIL");fail(503,"NATIVE_WORKER_CONTRACT_REJECTED",()->NativeImports.projection(raw));});
        check("ephemeral previews bind both owner and case and expire",()->{Time time=new Time();try(NativeImports imports=NativeImports.testCache(time)){String token=imports.save("a","c",1,offered());eq(imports.find("a","c",token).revision(),1L);fail(409,"NATIVE_PREVIEW_EXPIRED_REIMPORT",()->imports.find("b","c",token));fail(409,"NATIVE_PREVIEW_EXPIRED_REIMPORT",()->imports.find("a","d",token));time.now=time.now.plusSeconds(600);fail(409,"NATIVE_PREVIEW_EXPIRED_REIMPORT",()->imports.find("a","c",token));}});
        check("latest per-case preview replaces previous and account count is bounded",()->{try(NativeImports imports=NativeImports.testCache(Clock.systemUTC())){String old=imports.save("a","c",1,offered());String current=imports.save("a","c",1,offered());fail(409,"NATIVE_PREVIEW_EXPIRED_REIMPORT",()->imports.find("a","c",old));eq(imports.find("a","c",current).revision(),1L);for(int i=1;i<=3;i++)imports.save("a","c"+i,1,offered());fail(503,"NATIVE_PREVIEW_ACCOUNT_LIMIT",()->imports.save("a","limit",1,offered()));}});
        check("global preview capacity and shutdown deny new access",()->{NativeImports imports=NativeImports.testCache(Clock.systemUTC());for(int i=0;i<64;i++)imports.save("owner"+i,"c",1,offered());fail(503,"NATIVE_PREVIEW_CAPACITY",()->imports.save("overflow","c",1,offered()));imports.close();fail(503,"NATIVE_IMPORT_NOT_CONFIGURED",()->imports.save("a","c",1,offered()));});
        Path dir=Files.createTempDirectory("native-proposal-unit-");try(VaultStore store=new VaultStore(dir.resolve("data"),dir.resolve("key"))){Workspace w=new Workspace(store,Clock.systemUTC());String owner=(String)w.register(SelfServiceTests.body("username","native_owner","display_name","Synthetic owner","password","Synthetic-"+Workspace.id())).get("id");String other=(String)w.register(SelfServiceTests.body("username","native_other","display_name","Synthetic other","password","Synthetic-"+Workspace.id())).get("id");String preparer=(String)w.createOperator("native_preparer","Synthetic preparer","Synthetic-"+Workspace.id(),"PREPARER").get("id");
            check("selected native fields commit together as estimated and absent fields remain unknown",()->{String id=create(w,owner);var p=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->p);var row=w.readCase(owner,id);eq(Json.map(Json.map(row.get("inputs")).get("SALARY")),Map.of("state","ESTIMATED","amount","800000.00"));eq(Json.map(Json.map(row.get("inputs")).get("DEPOSIT_INTEREST")).get("state"),"UNKNOWN");eq(Json.map(row.get("native_import_links")).size(),2);eq(row.get("filing_available"),false);});
            check("a changed amount in one selection rolls back the entire multi-field action",()->{String id=create(w,owner);var row=w.readCase(owner,id);var p=preview(w,owner,id);var body=command(w,owner,id);body.put("selections",List.of(selection("SALARY","800000.00"),selection("SAVINGS_INTEREST","5001.00")));fail(409,"DISPLAYED_AMOUNT_CHANGED",()->w.proposeNative(owner,id,body,()->p));eq(w.readCase(owner,id),row);});
            check("missing whole-category or replacement review cannot create proposals",()->{String id=create(w,owner);var p=preview(w,owner,id);for(String flag:List.of("whole_category_confirmed","replace_input_confirmed")){var b=command(w,owner,id);var item=selection("SALARY","800000.00");item.put(flag,false);b.put("selections",List.of(item));fail(409,flag.equals("whole_category_confirmed")?"WHOLE_CATEGORY_REVIEW_REQUIRED":"REPLACEMENT_REVIEW_REQUIRED",()->w.proposeNative(owner,id,b,()->p));}});
            check("same-taxpayer review cannot be inferred from structural form matching",()->{String id=create(w,owner);var p=preview(w,owner,id);var b=command(w,owner,id);b.put("same_taxpayer_confirmed",false);fail(409,"NATIVE_SAME_TAXPAYER_REVIEW_REQUIRED",()->w.proposeNative(owner,id,b,()->p));eq(w.readCase(owner,id).containsKey("native_import_links"),false);});
            check("unoffered and repeated fields cannot be inferred or double-written",()->{String id=create(w,owner);var p=preview(w,owner,id);var b=command(w,owner,id);b.put("selections",List.of(selection("OTHER_INTEREST","0.00")));fail(409,"NATIVE_FIELD_NOT_OFFERED",()->w.proposeNative(owner,id,b,()->p));b.put("selections",List.of(selection("SALARY","800000.00"),selection("SALARY","800000.00")));fail(409,"NATIVE_FIELD_NOT_OFFERED",()->w.proposeNative(owner,id,b,()->p));});
            check("preview revision cannot be laundered with a fresh client revision",()->{String id=create(w,owner);var p=preview(w,owner,id);edit(w,owner,id,"RENAME","title","Changed");var b=command(w,owner,id);fail(409,"STALE_NATIVE_PREVIEW",()->w.proposeNative(owner,id,b,()->p));});
            check("accepted replay works without an ephemeral preview and preserves later edits",()->{String id=create(w,owner);var p=preview(w,owner,id);var b=command(w,owner,id);w.proposeNative(owner,id,b,()->p);edit(w,owner,id,"PROPOSE","field","SALARY","text","2 lakh","unit","");var row=w.readCase(owner,id);eq(w.proposeNative(owner,id,b,()->{throw new AssertionError("accepted replay consulted expired preview");}).get("status"),"REPLAYED");eq(w.readCase(owner,id),row);b.put("preview_id","B".repeat(43));fail(409,"IDEMPOTENCY_CONFLICT",()->w.proposeNative(owner,id,b,()->p));});
            check("confirmation is separate and retains only minimal source lineage",()->{String id=create(w,owner);var p=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->p);edit(w,owner,id,"CONFIRM","field","SALARY","amount","800000.00");var row=w.readCase(owner,id);eq(Json.map(Json.map(row.get("inputs")).get("SALARY")).get("state"),"CONFIRMED");eq(Json.map(row.get("native_import_links")).containsKey("SALARY"),true);});
            check("manual replacement and clearing remove native lineage for only that field",()->{String id=create(w,owner);var p=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->p);edit(w,owner,id,"PROPOSE","field","SALARY","text","1 lakh","unit","");eq(Json.map(w.readCase(owner,id).get("native_import_links")).containsKey("SALARY"),false);edit(w,owner,id,"CLEAR","field","SAVINGS_INTEREST");eq(w.readCase(owner,id).containsKey("native_import_links"),false);});
            check("other customer and an actively granted preparer cannot use new native routes or lineage",()->{String id=create(w,owner);var p=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->p);w.grant(owner,id,SelfServiceTests.body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preparer_username","native_preparer","expires_days",1L,"consent",true));for(String actor:List.of(other,preparer)){fail(404,"CASE_NOT_FOUND",()->w.nativeRevision(actor,id,1));fail(404,"CASE_NOT_FOUND",()->w.proposeNative(actor,id,command(w,owner,id),()->p));}eq(w.readCase(preparer,id).containsKey("native_import_links"),false);});
            check("same estimated amount from a new material snapshot makes scope review stale",()->{String id=create(w,owner);var first=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->first);w.saveItrScope(owner,id,SelfServiceTests.scopeBody(w,owner,id));eq(w.itrReadiness(owner,id).get("scope_review_current"),true);var second=preview(w,owner,id);w.proposeNative(owner,id,command(w,owner,id),()->second);eq(w.itrReadiness(owner,id).get("scope_review_current"),false);});
            check("operational audit never stores proposal amounts source payloads or identities",()->{String audit=Json.encode(w.audit(owner));for(String secret:List.of("800000.00","5000.00","ZZZZZ0000Z","GrossSalary","native_import_links","json_text"))eq(audit.contains(secret),false);});
        }finally{try(var files=Files.walk(dir)){for(Path p:files.sorted(java.util.Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
        System.out.println(Json.encode(Map.of("native_policy_groups",passed,"worker_process_tested_by_this_suite",false,"independent_tax_approval",false)));
    }
}
